import {STORAGE_KEY,freshState,normalizeState,stats,latestByQuestion,reviewIds,chooseQuestions,recordAnswer} from './core.mjs';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',questions:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',review:'<path d="M5 5h14v16l-7-4-7 4Z"/><path d="M9 3H3v14"/>',stats:'<path d="M4 20V4M4 20h17M8 16v-4M13 16V7M18 16V3"/>',sources:'<path d="M3 5h7l2 3h9v12H3Z"/><path d="M7 12h10M7 16h7"/>'};
const domains=[['総論','◎','#6e63b7','#eeebfa'],['技術','⌘','#5188a3','#e9f2f8'],['体腔液・尿・その他','◌','#4d947e','#e9f4ef'],['呼吸器','⌁','#ba8271','#fbefeb'],['消化器','◈','#b7974e','#fbf4e4'],['婦人科','❋','#ac7f9f','#f7edf4']];
const navItems=[['home','学習ホーム'],['questions','問題を選ぶ'],['review','復習ノート'],['stats','学習記録'],['sources','過去問資料']];
let questions=[],catalog=[],state=freshState(),storageProblem=false,dataWarning='',filter={domain:'all',filter:'all',search:''},reviewFilter='review',result=null,pendingImport=null,toastTimer;
const qById=id=>questions.find(q=>q.id===id);
const pdfFor=q=>`${catalog.find(y=>y.year===q.year)?.url}#page=${q.page}`;
const currentPage=()=>location.hash.slice(1).split('?')[0]||'home';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageProblem=false;}catch{storageProblem=true;toast('端末に保存できません。バックアップを書き出してください。');}}
function navigate(page){if(location.hash===`#${page}`)render();else location.hash=page;}
function warning(){return (storageProblem?'<div class="storage-warning" role="alert">ブラウザに保存できないため、現在の記録はこの画面を閉じると失われる場合があります。<button class="link-button" data-action="settings">バックアップを保存</button></div>':'')+(dataWarning?`<div class="storage-warning" role="alert">${esc(dataWarning)}</div>`:'');}
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]}</svg>`;}
function updateNav(page){$('#nav').innerHTML=navItems.map(([key,label])=>`<a href="#${key}" ${key===page?'class="active" aria-current="page"':''} aria-label="${label}">${icon(key)}<span>${label}</span>${key==='review'&&reviewIds(state).length?`<span class="nav-count">${reviewIds(state).length}</span>`:''}</a>`).join('');$('#page-label').textContent=navItems.find(x=>x[0]===page)?.[1]??(page==='result'?'学習結果':'演習');}
const art=`<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 240 220"><ellipse cx="125" cy="112" rx="107" ry="98" fill="#e1ddf7"/><ellipse cx="127" cy="111" rx="83" ry="77" fill="#f6f3ff" stroke="#c7bfe7" stroke-width="1.3" transform="rotate(-20 127 111)"/><path d="M67 84C57 52 105 30 141 47s71 60 43 99-88 39-111 3" fill="none" stroke="#dfd7f2" stroke-width="8" stroke-linecap="round"/><ellipse cx="130" cy="111" rx="36" ry="43" fill="#c6b9e4" stroke="#9e8ac6" stroke-width="1.3" transform="rotate(-28 130 111)"/><path d="m114 96 11-7 14 10-4 12 10 13-11 11-17-9 3-13Z" fill="#b5a1d5"/><circle cx="136" cy="107" r="11" fill="#8a73b6"/><path d="m63 111 12-4m-9 11 11-3m-7 9 10-4M159 69l10 6m-14 0 10 6m-14 0 10 6M154 156l12-5m-8 12 12-5" stroke="#b9acd3" stroke-width="3" stroke-linecap="round"/><circle cx="91" cy="67" r="5" fill="#d4dbab"/><circle cx="184" cy="117" r="4" fill="#d4dbab"/><circle cx="95" cy="151" r="5" fill="#d4dbab"/><circle cx="181" cy="41" r="13" fill="#e1e8c4"/><circle cx="33" cy="165" r="9" fill="#d7cee9"/><circle cx="211" cy="169" r="5" fill="#bfb3d9"/><path d="M19 65h12m-6-6v12M202 91h10m-5-5v10" stroke="#b6accf" stroke-width="1.5"/></svg></div>`;
function intro(eyebrow,title,desc){return `<div class="page-intro"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>`;}
function metric(label,value,unit,sub,color){return `<div class="metric"><div class="metric-label"><i class="metric-dot" style="background:${color??'#aaa1de'}"></i>${label}</div><div class="metric-value">${value}<span class="metric-unit">${unit}</span></div><div class="metric-sub">${sub}</div></div>`;}
function resumeCard(){const s=state.session;if(!s)return '';return `<div class="resume"><div><b>前回の続きがあります</b><small>${esc(s.label)} · ${s.index+1} / ${s.queue.length}問目</small></div><button class="button secondary" data-action="resume">再開する →</button></div>`;}
function home(){const st=stats(state,questions);const latest=latestByQuestion(state);return `${intro('YOUR DAILY LEARNING','おかえりなさい。','無理のないペースで、今日の学びを始めましょう。')}
<section class="hero"><div class="hero-copy"><div class="eyebrow">ONE QUESTION, ONE STEP.</div><h1>今日の一問が、<br>確かな知識に。</h1><p>原本で解く。根拠を知る。もう一度、確かめる。<br>細胞検査士を目指す、あなたの学習ノート。</p><div class="hero-actions"><button class="button primary" data-action="daily" data-count="5" ${questions.length?'':'disabled'}>今日の5問を始める <span class="arrow">→</span></button><button class="button secondary" data-action="daily" data-count="10" ${questions.length?'':'disabled'}>10問に挑戦</button></div></div>${art}</section>${resumeCard()}
<div class="metric-grid">${metric('学習した問題',st.answered,'問',`採点対応 ${questions.length}問のうち`)}${metric('初回の正答率',st.rate??'—','%',st.answered?'各問題の初回回答で集計':'問題を解くと記録されます','#8bb5a7')}${metric('復習したい問題',st.review,'問','不正解・迷った問題','#c5a272')}${metric('過去問の原本',catalog.length,'年分','2014〜2025年度を参照','#9bafd0')}</div>
<div class="home-lower"><section><div class="row-heading"><h2>領域から学ぶ</h2><a href="#questions">問題一覧を見る →</a></div><div class="domain-grid">${domains.map(([d,sym,color,soft])=>{const qs=questions.filter(q=>q.domain===d),done=qs.filter(q=>latest.has(q.id)).length;return `<a class="domain-card" href="${qs.length?'#questions?domain='+encodeURIComponent(d):'#sources'}" style="--color:${color};--soft:${soft}"><div class="domain-top"><span class="domain-symbol">${sym}</span><div><h3>${d}</h3><small>${qs.length?`2025年度 · ${qs.length}問`:'原本PDFで学ぶ'}</small></div><span class="chevron">›</span></div><div class="domain-bottom"><div class="progress-meta"><span>${qs.length?`${done} / ${qs.length}問 学習済み`:'解答を調査中'}</span><span>${qs.length?Math.round(done/qs.length*100)+'%':'資料を見る ↗'}</span></div><div class="progress-track"><span style="width:${qs.length?done/qs.length*100:0}%"></span></div></div></a>`}).join('')}</div></section>
<aside class="home-aside"><div><div class="row-heading"><h2>記憶を、確かなものに。</h2></div><div class="review-card"><span class="tag">REVIEW NOTE</span><div class="review-number">${st.review}<span class="metric-unit">問</span></div><p>${st.review?'間違えた問題、迷いながら選んだ問題。<br>もう一度解いて、理解を確かめましょう。':'復習ノートは、まだ空っぽです。<br>間違えた問題と「迷った」問題が<br>ここに集まります。'}</p><a class="button secondary" href="#review">復習ノートを開く →</a></div></div><div class="step-guide"><h3>このノートの使い方</h3><ol class="steps"><li>学会の原本PDFで問題を読む</li><li>アプリで選択肢の番号を選ぶ</li><li>解説と出典を読み、復習へ</li></ol></div></aside></div>
<div class="info-strip"><span>ⓘ</span><div><strong>出典が分かる、筆記学習。</strong> 採点には文献調査による独自解答を使います。公式正答とは区別し、根拠を十分に確認できない問題は採点対象に含めません。</div></div>`;}
function statusTag(q){const a=latestByQuestion(state).get(q.id);return !a?'<span class="tag">未回答</span>':`<span class="tag ${a.correct?'green':'red'}">${a.correct?(a.confidence==='unsure'?'正解・迷った':'正解'):'要復習'}</span>`;}
function questionRows(qs){return `<div class="question-list">${qs.map(q=>`<div class="question-row"><span class="question-number">Q.${q.number}</span><div class="question-detail"><h3><a href="#" data-action="single" data-id="${q.id}">${esc(q.title)}</a></h3><div class="question-meta"><span>${q.year}年度</span><span>${q.domain}</span><span>${q.selectCount===2?'2つ選択':q.format==='combination'?'組合せ':'1つ選択'}</span></div></div>${statusTag(q)}<button class="icon-button ${state.bookmarks.includes(q.id)?'saved':''}" data-action="bookmark" data-id="${q.id}" aria-label="問題${q.number}を${state.bookmarks.includes(q.id)?'保存から外す':'保存する'}" aria-pressed="${state.bookmarks.includes(q.id)}">${state.bookmarks.includes(q.id)?'★':'☆'}</button></div>`).join('')}</div>`;}
function empty(title,desc,link='questions',label='問題を選ぶ'){return `<div class="empty"><div class="empty-symbol">◎</div><h2>${title}</h2><p>${desc}</p><a class="button secondary" href="#${link}">${label} →</a></div>`;}
function questionPage(){const qs=chooseQuestions(questions,state,filter);return `${intro('QUESTION LIBRARY','学びたい問題を、見つけよう。','領域・学習状況から選べます。現在の採点対応は2025年度です。')}${resumeCard()}<form id="filters" class="toolbar"><div class="field"><label for="domain-filter">領域</label><select id="domain-filter"><option value="all">すべての領域</option>${domains.map(([d])=>`<option ${filter.domain===d?'selected':''}>${d}</option>`).join('')}</select></div><div class="field"><label for="status-filter">学習状況</label><select id="status-filter">${[['all','すべて'],['unanswered','未回答'],['wrong','間違えた'],['unsure','迷った'],['saved','保存した']].map(([v,t])=>`<option value="${v}" ${filter.filter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field search-field"><label for="search-input">トピック・問題番号</label><input id="search-input" type="search" placeholder="例：染色、壊死、15" value="${esc(filter.search)}"></div><button type="submit" class="button secondary">絞り込む</button></form><div class="row-heading"><p class="list-count"><strong>${qs.length}問</strong> が見つかりました</p><button class="button primary" data-action="filtered" ${qs.length?'':'disabled'}>この条件で解く →</button></div>${qs.length?questionRows(qs):empty('該当する問題がありません','条件を変更するか、過去問資料から原本PDFを参照してください。','sources','過去問資料を見る')}`;}
function reviewPage(){const qs=chooseQuestions(questions,state,{filter:reviewFilter});return `${intro('REVIEW NOTE','「迷った」を、分かるに変える。','直近の回答が不正解、または「迷った」の問題を集めています。自信を持って正解すると復習対象から外れます。')}<div class="filter-tabs">${[['review','復習対象'],['wrong','間違えた'],['unsure','迷った'],['saved','保存した']].map(([k,t])=>`<button data-action="review-filter" data-filter="${k}" class="${reviewFilter===k?'active':''}">${t}</button>`).join('')}</div><div class="row-heading"><p class="list-count"><strong>${qs.length}問</strong></p><button class="button primary" data-action="review-start" ${qs.length?'':'disabled'}>まとめて復習 →</button></div>${qs.length?questionRows(qs):empty(reviewFilter==='saved'?'保存した問題はありません':'復習対象はありません',reviewFilter==='saved'?'気になる問題の ☆ を押すと、ここから見返せます。':'問題を解いた結果と「迷った」の記録が、ここに反映されます。')}`;}
function quizPage(){const s=state.session;if(!s)return empty('演習を始めましょう','領域や学習状況から問題を選べます。');const q=qById(s.queue[s.index]);const a=s.submitted?state.attempts.findLast(a=>a.sessionId===s.id&&a.id===q.id):null;const combos=['A・B','A・E','B・C','C・D','D・E'];return `<div class="quiz-top"><button class="link-button" data-action="pause">← 中断してホームへ</button><div class="quiz-counter"><b>${s.index+1}</b> / ${s.queue.length} 問</div></div><div class="quiz-progress"><span style="width:${(s.index+(s.submitted?1:0))/s.queue.length*100}%"></span></div><article class="quiz-panel"><div class="quiz-header"><div class="quiz-kicker"><span class="tag">${q.domain}</span><span>${q.year}年度 / 第${q.round}回</span><span>問題 ${q.number}</span></div><button class="icon-button ${state.bookmarks.includes(q.id)?'saved':''}" data-action="bookmark" data-id="${q.id}" aria-label="この問題を保存" aria-pressed="${state.bookmarks.includes(q.id)}">${state.bookmarks.includes(q.id)?'★':'☆'}</button></div><h1>${esc(q.title)}</h1><div class="source-box"><strong>原本の「問題 ${q.number}」を読んで解答してください</strong><p>学会の公式PDF・${q.page}ページ目を参照します。この画面の題名は学習用トピックです。<br>原本の「正しい／誤っている」と選択数も確認しましょう。</p><div class="source-actions"><a class="button secondary" href="${pdfFor(q)}" target="_blank" rel="noopener noreferrer">原本PDFを開く ↗</a><button class="link-button" data-action="toggle-pdf" aria-expanded="false">この画面で原本を見る</button></div><div id="pdf-slot"></div></div><div class="select-label"><strong>${q.selectCount===2?'正しい番号を2つ選択':'解答の番号を1つ選択'}</strong><small>${q.format==='combination'?'組合せは原本と同じ対応です':'選択肢の内容は原本を参照'}</small></div><div class="choices" role="group" aria-label="解答の選択">${[1,2,3,4,5].map(n=>`<button class="choice ${s.selected.includes(n)?'selected':''} ${a?(q.answer.includes(n)?'correct':s.selected.includes(n)?'wrong':''):''}" data-action="select" data-value="${n}" aria-pressed="${s.selected.includes(n)}" aria-label="選択肢${n}${q.format==='combination'?' '+combos[n-1]:''}" ${a?'disabled':''}><strong>${n}</strong>${q.format==='combination'?`<small>${combos[n-1]}</small>`:''}</button>`).join('')}</div><div class="confidence-row"><span>回答への自信を記録</span><div class="segmented"><button data-action="confidence" data-value="sure" class="${s.confidence==='sure'?'active':''}" aria-pressed="${s.confidence==='sure'}" ${a?'disabled':''}>自信あり</button><button data-action="confidence" data-value="unsure" class="${s.confidence==='unsure'?'active':''}" aria-pressed="${s.confidence==='unsure'}" ${a?'disabled':''}>迷った</button></div></div>${a?answerPanel(q,a):`<div class="submit-row"><p>回答確定後に解説と根拠を表示します。</p><button class="button primary" data-action="submit" ${s.selected.length===q.selectCount?'':'disabled'}>回答を確定する →</button></div>`}</article>`;}
function answerPanel(q,a){return `<section class="answer-panel" id="answer-panel" tabindex="-1"><div class="answer-banner ${a.correct?'':'incorrect'}"><b>${a.correct?'✓ 正解':'もう一度、確認しよう'}</b><span>解答：${q.answer.join('・')}${a.correct?'':`　あなたの回答：${a.selected.join('・')}`}</span><small>文献調査による解答</small></div><h2>理解のポイント</h2><p class="explanation">${esc(q.explanation)}</p><details class="disclosure"><summary>選択肢ごとの考え方</summary>${q.optionNotes.map(o=>`<div class="option-note"><b>${esc(o.label)}</b><span>${esc(o.text)}</span></div>`).join('')}</details><h3>根拠をたどる</h3><ul class="sources-list">${q.sources.map(src=>`<li><a href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">${esc(src.title)} ↗</a><small>${esc(src.kind)}${src.locator?' · '+esc(src.locator):''}</small></li>`).join('')}</ul><p class="small">確認日：${q.checkedAt} · 独自解答。学会の公式正答・専門家による監修済みを意味しません。</p><label for="study-note"><h3>自分のことばで、ひとこと。</h3></label><textarea id="study-note" class="note-input" maxlength="4000" placeholder="覚えたいこと、迷った理由など。入力するとこの端末に保存されます。" data-id="${q.id}">${esc(state.notes[q.id]??'')}</textarea><small>メモはこの端末に自動保存</small><div class="next-row"><button class="button primary" data-action="next">${state.session.index===state.session.queue.length-1?'結果を見る':'次の問題へ'} →</button></div></section>`;}
function resultPage(){if(!result)return empty('学習記録を確認できます','これまでの回答は学習記録に保存されています。','stats','学習記録を見る');const {attempts,queue,label}=result;const correct=attempts.filter(a=>a.correct).length;const wrong=attempts.filter(a=>!a.correct||a.confidence==='unsure').length;return `<div class="result-card"><div class="eyebrow">SESSION COMPLETE</div><h1>今日も、一歩前へ。</h1><p class="muted">${esc(label)}の学習が完了しました。</p><div class="score-ring" style="--score:${attempts.length?100*correct/attempts.length:0}"><strong>${correct}<small> / ${queue.length}</small></strong></div><p class="result-meta">正解 ${correct}問 · 不正解 ${attempts.length-correct}問 · 迷った ${attempts.filter(a=>a.confidence==='unsure').length}問</p><p class="small">今回の筆記演習の成績です。認定試験の合否を示すものではありません。</p><div class="hero-actions"><button class="button primary" data-action="result-review" ${wrong?'':'disabled'}>復習する（${wrong}問）</button><a class="button secondary" href="#home">ホームへ戻る</a></div></div><div class="row-heading"><h2>今回の問題</h2><span class="small">題名を押すと、もう一度解けます。</span></div>${questionRows(queue.map(qById).filter(Boolean))}`;}
function statsPage(){const st=stats(state,questions);const now=new Date();const days=Array.from({length:7},(_,i)=>{const d=new Date(now);d.setDate(d.getDate()-6+i);const key=d.toLocaleDateString('en-CA');return {label:`${d.getMonth()+1}/${d.getDate()}`,count:state.attempts.filter(a=>new Date(a.at).toLocaleDateString('en-CA')===key).length}});const max=Math.max(1,...days.map(d=>d.count));return `${intro('YOUR PROGRESS','積み重ねが、見えてくる。','初回の理解度と、復習を含む学習量を分けて振り返れます。')}<div class="metric-grid">${metric('学習した問題',st.answered,'問','異なる問題の数')}${metric('初回の正答率',st.rate??'—','%',`初回正解 ${st.correct}問`,'#8bb5a7')}${metric('累計の回答',st.attempts,'回','復習を含むすべての回答','#9bafd0')}${metric('復習対象',st.review,'問','直近の不正解・迷った問題','#c5a272')}</div><div class="two-col"><section class="panel"><h2>この7日間の学習</h2><p class="small">回答した回数 · 端末の現地日付</p><div class="chart" role="img" aria-label="${days.map(d=>d.label+' '+d.count+'回').join('、')}">${days.map(d=>`<div class="chart-day"><span>${d.count}</span><i style="height:${Math.max(2,d.count/max*100)}px"></i><small>${d.label}</small></div>`).join('')}</div></section><section class="panel"><h2>領域別の初回正答率</h2>${domains.filter(([d])=>questions.some(q=>q.domain===d)).map(([d,,color])=>{const ds=stats(state,questions.filter(q=>q.domain===d));return `<div class="stat-domain" style="--color:${color}"><div class="progress-meta"><span>${d}</span><span>${ds.rate??'—'}% · ${ds.answered}問</span></div><div class="progress-track"><span style="width:${ds.rate??0}%"></span></div></div>`}).join('')}</section></div><div class="info-strip"><span>◷</span><div>記録はこのブラウザに保存されています。端末の変更やデータ消去に備えて、<button class="link-button" data-action="settings">バックアップ</button>を残せます。</div></div>`;}
function sourcesPage(){return `${intro('SOURCE LIBRARY','学びの原点へ。','学会の公開過去問と、解答の調査状況をまとめています。')}<div class="info-strip" style="margin:0 0 23px"><span>ⓘ</span><div><strong>原本 ${catalog.length}年度分 / 採点対応 ${questions.length}問</strong><br>原本の収集先と、アプリで採点できる問題数は別です。採点対応は根拠を調べた2025年度の一部で、問題ごとに解説と出典を表示します。</div></div><div class="catalog-grid">${catalog.map(y=>{const count=questions.filter(q=>q.year===y.year).length;return `<article class="year-card"><h3>${y.year}<span class="metric-unit">年度</span></h3><p>第${y.round}回 · 筆記試験 · PDF ${y.pages}ページ</p><span class="tag">${count?`アプリで${count}問を採点`:'原本参照のみ'}</span><br><a href="${y.url}" target="_blank" rel="noopener noreferrer">学会の原本PDFを開く ↗</a></article>`}).join('')}</div><section class="text-panel"><h2>解答と解説の扱い</h2><p>学会の公式正答、大学・教育機関の模範解答、文献調査による解答を区別します。現在の採点対象はすべて文献調査による独自解答です。解答を一意に決められない問題、根拠が不足する問題は演習から外しています。</p><p>各問題の出題年・選択形式に合わせて調べ、解説に根拠のリンクを付けています。誤りが判明した際は解答を改訂します。公式正答や専門家の監修を保証するものではありません。</p><h3>大学の教育資料も調査対象に</h3><p>畿央大学の臨床細胞学研修センターで筆記模範解答の提供案内を確認しています。有料教材の解答本体は未取得で、このアプリへの転記もしていません。<a href="https://cytology.kio.ac.jp/ctcen/wsi/?lang=JP&tab=1" target="_blank" rel="noopener noreferrer">大学の教材案内 ↗</a></p><h3>問題本文と利用方法</h3><p>問題本文は学会の公式PDFを開いて参照する形式です。PCでは演習画面内にも原本を表示できます。スマートフォンでPDFが見づらい場合は、別タブまたは別の端末で原本を開いてください。原本の文面や選択肢をアプリ内に転載していません。</p><h3>公開・プライバシー</h3><p>無料で利用できます。検索エンジンへの掲載を避ける設定にしていますが、URLを知る人はアクセスできます。ログインや個人情報の入力は不要です。回答・メモをサーバーに送信する機能はありません。原本や根拠リンクを開くと、提供元の外部サイトに移動します。</p><p class="small">過去問の収集先確認：2026年9月 / 解答調査・アプリ更新：2026年11月3日</p></section>`;}
function render({scroll=true}={}){const page=currentPage();updateNav(page);const view={home,questions:questionPage,review:reviewPage,quiz:quizPage,result:resultPage,stats:statsPage,sources:sourcesPage}[page]??home;$('#main').innerHTML=warning()+view();document.title=`${navItems.find(x=>x[0]===page)?.[1]??(page==='quiz'?'演習':'学習結果')}｜CytoNote`;if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function start(qs,label){if(!qs.length){toast('この条件に合う問題はありません。');return;}if(state.session&&!window.confirm('中断中の演習を終了し、新しい演習を始めますか？ 確定済みの回答履歴は残ります。'))return;state.session={id:crypto.randomUUID(),queue:qs.map(q=>q.id),index:0,startedAt:new Date().toISOString(),label,selected:[],confidence:'sure',submitted:false};save();navigate('quiz');}
function onAction(e){const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const action=b.dataset.action;const s=state.session;switch(action){
 case 'daily':{let qs=chooseQuestions(questions,state,{filter:'unanswered',shuffle:true});if(qs.length<Number(b.dataset.count)){const seen=new Set(qs.map(q=>q.id));qs.push(...chooseQuestions(questions,state,{shuffle:true}).filter(q=>!seen.has(q.id)));}start(qs.slice(0,Number(b.dataset.count)),`今日の${Math.min(Number(b.dataset.count),questions.length)}問`);break;}
 case 'single':start([qById(b.dataset.id)],'1問演習');break;
 case 'filtered':start(chooseQuestions(questions,state,filter),filter.domain==='all'?'選んだ問題':filter.domain);break;
 case 'review-start':start(chooseQuestions(questions,state,{filter:reviewFilter}),'復習');break;
 case 'review-filter':reviewFilter=b.dataset.filter;render({scroll:false});break;
 case 'resume':navigate('quiz');break;
 case 'pause':save();navigate('home');break;
 case 'bookmark':{const id=b.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(v=>v!==id):[...state.bookmarks,id];save();render({scroll:false});toast(state.bookmarks.includes(id)?'復習ノートに保存しました':'保存を解除しました');break;}
 case 'select':if(s&&!s.submitted){const n=Number(b.dataset.value),q=qById(s.queue[s.index]);if(q.selectCount===1)s.selected=[n];else if(s.selected.includes(n))s.selected=s.selected.filter(v=>v!==n);else if(s.selected.length<q.selectCount)s.selected.push(n);else{toast('2つ選択済みです。選択を外して変更してください。');break;}save();updateQuizControls();}break;
 case 'confidence':if(s&&!s.submitted){s.confidence=b.dataset.value;save();updateQuizControls();}break;
 case 'submit':if(s){try{recordAnswer(state,qById(s.queue[s.index]),s.selected,s.confidence);save();render({scroll:false});$('#answer-panel')?.focus({preventScroll:true});$('#answer-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(err){toast(err.message);}}break;
 case 'next':if(s&&s.submitted){if(s.index===s.queue.length-1){result={queue:[...s.queue],label:s.label,attempts:state.attempts.filter(a=>a.sessionId===s.id)};state.session=null;save();navigate('result');}else{s.index++;s.selected=[];s.submitted=false;s.confidence='sure';save();render();}}break;
 case 'result-review':if(result)start(result.attempts.filter(a=>!a.correct||a.confidence==='unsure').map(a=>qById(a.id)),'今回の復習');break;
 case 'toggle-pdf':{const slot=$('#pdf-slot');if(slot.innerHTML){slot.innerHTML='';b.textContent='この画面で原本を見る';b.setAttribute('aria-expanded','false');}else{const q=qById(s.queue[s.index]);slot.innerHTML=`<p class="small" style="margin-top:12px">表示されない場合は「原本PDFを開く」を使ってください。</p><iframe class="pdf-view" src="${pdfFor(q)}" title="${q.year}年度 公式過去問PDF" loading="lazy" referrerpolicy="no-referrer"></iframe>`;b.textContent='原本を閉じる';b.setAttribute('aria-expanded','true');}break;}
 case 'settings':$('#settings').showModal();break;
 case 'close-settings':$('#settings').close();break;
 case 'export':{const blob=new Blob([JSON.stringify({app:'CytoNote',exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`cytonote-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('バックアップを書き出しました');break;}
 case 'import-confirm':if(pendingImport){state=pendingImport;pendingImport=null;save();$('#import-preview').innerHTML='';$('#settings').close();navigate('home');toast('バックアップを読み込みました');}break;
 case 'import-cancel':pendingImport=null;$('#import-preview').innerHTML='';break;
 }}
function updateQuizControls(){const s=state.session,q=qById(s.queue[s.index]);document.querySelectorAll('[data-action="select"]').forEach(b=>{const on=s.selected.includes(Number(b.dataset.value));b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});document.querySelectorAll('[data-action="confidence"]').forEach(b=>{const on=s.confidence===b.dataset.value;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});const submit=$('[data-action="submit"]');if(submit)submit.disabled=s.selected.length!==q.selectCount;}
document.addEventListener('click',onAction);
document.addEventListener('submit',e=>{if(e.target.id==='filters'){e.preventDefault();filter={domain:$('#domain-filter').value,filter:$('#status-filter').value,search:$('#search-input').value};render({scroll:false});}});
document.addEventListener('input',e=>{if(e.target.id==='study-note'){state.notes[e.target.dataset.id]=e.target.value;save();}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw new Error('2MB以下のバックアップを選んでください。');const raw=JSON.parse(await file.text());if(raw.app!=='CytoNote')throw new Error('CytoNoteのバックアップを選んでください。');pendingImport=normalizeState(raw,questions);$('#import-preview').innerHTML=`<div class="info-strip"><div><strong>${pendingImport.attempts.length}回の回答を読み込みます。</strong><br>現在の${state.attempts.length}回の履歴を置き換えます。<div class="settings-actions"><button class="button primary" data-action="import-confirm">置き換えて読み込む</button><button class="button secondary" data-action="import-cancel">キャンセル</button></div></div></div>`;}catch(err){pendingImport=null;$('#import-preview').innerHTML=`<p class="error">${esc(err.message)}</p>`;}e.target.value='';});
window.addEventListener('hashchange',()=>{const params=new URLSearchParams(location.hash.split('?')[1]??'');if(currentPage()==='questions'&&params.has('domain'))filter={domain:params.get('domain'),filter:'all',search:''};render();$('#main').focus({preventScroll:true});});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY&&e.newValue){try{state=normalizeState(JSON.parse(e.newValue),questions);render({scroll:false});toast('別のタブで更新された学習記録を反映しました。');}catch{}}});
try{
 const [qres,cres]=await Promise.all([fetch('./questions.json'),fetch('./catalog.json')]);if(!qres.ok||!cres.ok)throw new Error('教材を読み込めませんでした。');
 const bank=await qres.json();questions=bank.questions.filter(q=>q.status==='researched'&&q.answer.length===q.selectCount);catalog=await cres.json();
 try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)state=normalizeState(JSON.parse(raw),questions);}catch{storageProblem=true;dataWarning='保存データを読み込めませんでした。データの自動削除はしていません。';}
 const params=new URLSearchParams(location.hash.split('?')[1]??'');if(params.has('domain'))filter.domain=params.get('domain');render();
}catch(err){$('#main').innerHTML=empty('教材を読み込めませんでした','通信を確認して、このページを再読み込みしてください。','home','ホームへ');$('#main').insertAdjacentHTML('beforeend',`<p class="error">${esc(err.message)}</p>`);}
